import { execFileSync } from 'node:child_process'

// LIVE MAIN: fixed aggregate queries only, zero mutations and no client PII.
// Dates use UTC day extracted from stored creation timestamps.
// Before Nov 1-7, after Nov 9-15, Nov 8 release transition excluded.
function select(label,sql){
  if(!/^\s*SELECT\b/i.test(sql)||/;|\b(INSERT|UPDATE|DELETE|REPLACE|ALTER|DROP|CREATE|ATTACH|DETACH|PRAGMA|VACUUM)\b/i.test(sql))
    throw new Error('Forbidden SQL action: '+label)
  const raw=execFileSync('npx',['--no-install','wrangler','d1','execute','orders_db_prod','--config','wrangler.jsonc','--remote','--json','--command',sql],{encoding:'utf8',timeout:120000,maxBuffer:32*1024*1024})
  const result=JSON.parse(raw)
  if(!Array.isArray(result)||result.some(x=>x.success!==true))throw new Error('D1 failed '+label)
  return result.flatMap(x=>x.results||[])
}
const schema=select('schema',"SELECT name,sql FROM sqlite_master WHERE type='table' AND name IN ('orders','order_items','inventory_reservations','inventory_movements','inventory_stock_checks','inventory_operation_evidence','inventory_lifecycle_events')")
console.log('COMPARISON_SCHEMA_COLUMNS '+JSON.stringify(schema.map(x=>({table:x.name,columns:[...String(x.sql).matchAll(/^\s*([a-zA-Z][a-zA-Z_0-9]*)\s+(?:INTEGER|TEXT|REAL|BLOB|NUMERIC)\b/gm)].map(x=>x[1])}))))
const dailyOrders=select('orders',"SELECT substr(created_at,1,10) AS day,COUNT(*) AS orders_count,SUM(CASE WHEN order_status='deleted' THEN 1 ELSE 0 END) AS deleted,SUM(CASE WHEN order_status='archived' THEN 1 ELSE 0 END) AS archived,SUM(CASE WHEN shipping_status='sent' THEN 1 ELSE 0 END) AS sent_now, SUM(CASE WHEN source_type='workshop' THEN 1 ELSE 0 END) AS workshop_primary, SUM(CASE WHEN pricing_mode='itemized_v1' THEN 1 ELSE 0 END) AS itemized FROM orders WHERE created_at >= '2026-10-18' AND created_at < '2026-11-17' GROUP BY substr(created_at,1,10) ORDER BY day")
const dailyItems=select('items',"SELECT substr(o.created_at,1,10) AS day,COUNT(*) AS lines,SUM(CASE WHEN oi.variant_id IS NULL THEN 1 ELSE 0 END) AS no_variant_lines,SUM(CASE WHEN oi.product_id IS NULL THEN 1 ELSE 0 END) AS no_product_lines,SUM(CASE WHEN oi.is_workshop=1 THEN 1 ELSE 0 END) AS workshop_lines,SUM(CASE WHEN oi.is_workshop=0 THEN 1 ELSE 0 END) AS stock_lines,SUM(CASE WHEN oi.is_workshop=0 AND oi.variant_id IS NULL THEN 1 ELSE 0 END) AS stock_unresolved_lines,SUM(oi.quantity) AS quantity FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.created_at >= '2026-10-18' AND o.created_at < '2026-11-17' GROUP BY substr(o.created_at,1,10) ORDER BY day")
const dailyMovements=select('movements',"SELECT substr(created_at,1,10) AS day,movement_type,COUNT(*) AS movement_rows,SUM(CASE WHEN quantity_delta!=0 THEN 1 ELSE 0 END) AS nonzero_movements,SUM(ABS(quantity_delta)) AS absolute_units,SUM(quantity_delta) AS net_units,COUNT(DISTINCT COALESCE(reference_type,'') || ':' || COALESCE(reference_id,CAST(id AS TEXT))) AS distinct_operations FROM inventory_movements WHERE created_at >= '2026-10-18' AND created_at < '2026-11-17' GROUP BY substr(created_at,1,10),movement_type ORDER BY day,movement_type")
const manualReferences=select('manualReferences',"SELECT CASE WHEN created_at<'2026-11-01' THEN 'Oct18-31' WHEN created_at<'2026-11-08' THEN 'Nov1-7' WHEN created_at<'2026-11-09' THEN 'Nov8' WHEN created_at<'2026-11-16' THEN 'Nov9-15' ELSE 'Nov16' END AS period,movement_type,COALESCE(NULLIF(reference_type,''),'(empty)') AS reference_type,COUNT(*) AS movement_rows,SUM(ABS(quantity_delta)) AS abs_units FROM inventory_movements WHERE movement_type IN ('manual_set','revision','writeoff') AND created_at >= '2026-10-18' AND created_at<'2026-11-17' GROUP BY period,movement_type,reference_type ORDER BY period,movement_rows DESC")
const dailyChecks=select('checks',"SELECT substr(checked_at,1,10) AS day,check_type,COUNT(*) AS checks,SUM(CASE WHEN difference_quantity!=0 THEN 1 ELSE 0 END) AS mismatches,SUM(ABS(difference_quantity)) AS abs_difference_units FROM inventory_stock_checks WHERE checked_at >= '2026-10-18' AND checked_at < '2026-11-17' GROUP BY substr(checked_at,1,10),check_type ORDER BY day,check_type")
const dailyReservations=select('reservations',"SELECT substr(created_at,1,10) AS day,status,COALESCE(NULLIF(unresolved_reason,''),'(none)') AS reason,COUNT(*) AS rows,SUM(quantity) AS qty,SUM(CASE WHEN variant_id IS NULL OR variant_id=0 THEN 1 ELSE 0 END) AS unknown_sku FROM inventory_reservations WHERE created_at >= '2026-10-18' AND created_at<'2026-11-17' GROUP BY substr(created_at,1,10),status,reason ORDER BY day,status,rows DESC")
const currentUnresolved=select('unresolved',"SELECT COALESCE(NULLIF(r.unresolved_reason,''),'(none)') AS reason,r.inventory_source AS source,CASE WHEN r.variant_id IS NULL OR r.variant_id=0 THEN 'unknown_sku' ELSE 'known_sku' END AS identity,COALESCE(o.order_status,'missing_order') AS order_status,COALESCE(o.shipping_status,'missing_shipping') AS shipping_status,CASE WHEN o.created_at<'2026-11-01' THEN 'before_Nov' WHEN o.created_at<'2026-11-08' THEN 'Nov1-7' WHEN o.created_at<'2026-11-09' THEN 'Nov8' WHEN o.created_at<'2026-11-16' THEN 'Nov9-15' ELSE 'Nov16' END AS order_period,COUNT(*) AS rows,SUM(r.quantity) AS qty,MIN(substr(o.created_at,1,10)) AS oldest_order_day,MAX(substr(o.created_at,1,10)) AS newest_order_day FROM inventory_reservations r LEFT JOIN orders o ON o.id=r.order_id WHERE r.status='unresolved' GROUP BY reason,source,identity,order_status,shipping_status,order_period ORDER BY rows DESC")
const recentOrderReserves=select('recentOrderReserves',"SELECT substr(o.created_at,1,10) AS order_day,COUNT(DISTINCT o.id) AS orders_with_reserves,COUNT(*) AS reserve_lines,SUM(CASE WHEN r.status='unresolved' THEN 1 ELSE 0 END) AS currently_unresolved_lines,SUM(CASE WHEN r.status='active' THEN 1 ELSE 0 END) AS currently_active_lines,SUM(CASE WHEN r.status='fulfilled' THEN 1 ELSE 0 END) AS fulfilled_lines,SUM(CASE WHEN r.status='released' THEN 1 ELSE 0 END) AS released_lines FROM inventory_reservations r JOIN orders o ON o.id=r.order_id WHERE o.created_at>='2026-10-18' AND o.created_at<'2026-11-17' GROUP BY substr(o.created_at,1,10) ORDER BY order_day")
const currentUnresolvedSku=select('unresolvedSku',"SELECT COALESCE(NULLIF(r.unresolved_reason,''),'(none)') AS reason,CASE WHEN r.variant_id IS NULL OR r.variant_id=0 THEN 'unknown_sku' ELSE 'known_sku' END AS identity,COUNT(*) AS rows,SUM(r.quantity) AS qty, SUM(CASE WHEN s.id IS NULL THEN 1 ELSE 0 END) AS without_stock_row, SUM(CASE WHEN s.id IS NOT NULL AND s.quantity<s.reserved_quantity THEN 1 ELSE 0 END) AS linked_to_current_shortage FROM inventory_reservations r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.status='unresolved' GROUP BY reason,identity ORDER BY rows DESC")
const report={periods:{baseline_1:'2026-10-25..2026-10-31',baseline_2:'2026-11-01..2026-11-07',release_day:'2026-11-08',post:'2026-11-09..2026-11-15'},dailyOrders,dailyItems,dailyMovements,manualReferences,dailyChecks,dailyReservations,currentUnresolved,recentOrderReserves,currentUnresolvedSku}
console.log('PICKER_IMPACT_MAIN_READONLY_JSON '+JSON.stringify(report))
